-- Log evidence deletions
CREATE OR REPLACE FUNCTION log_evidence_deleted()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO ticket_activity (
    ticket_id,
    activity_type,
    actor_profile_id,
    note,
    metadata
  ) VALUES (
    OLD.ticket_id,
    'EVIDENCE_DELETED',
    auth.uid(),
    'Evidencia eliminada',
    jsonb_build_object('file_url', OLD.file_url, 'evidence_id', OLD.id)
  );
  RETURN OLD;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER trigger_log_evidence_deleted
  BEFORE DELETE ON ticket_evidences
  FOR EACH ROW
  EXECUTE FUNCTION log_evidence_deleted();

