-- Log technician notes changes
CREATE OR REPLACE FUNCTION log_technician_note_change()
RETURNS TRIGGER AS $$
BEGIN
  -- Only log if technician_notes changed and is not null/empty
  IF OLD.technician_notes IS DISTINCT FROM NEW.technician_notes
     AND NEW.technician_notes IS NOT NULL
     AND trim(NEW.technician_notes) != '' THEN

    INSERT INTO ticket_activity (
      ticket_id,
      activity_type,
      actor_profile_id,
      note
    ) VALUES (
      NEW.id,
      'TECHNICIAN_NOTE_ADDED',
      auth.uid(),
      NEW.technician_notes
    );
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER trigger_log_technician_note_change
  AFTER UPDATE OF technician_notes ON tickets
  FOR EACH ROW
  EXECUTE FUNCTION log_technician_note_change();

